window.FS_CT=window.FS_CT||{};FS_CT["cpp"]={"id":"cpp","title":"C++","lang":"cpp","kind":"lang","desc":"Language-specific practice: cin/cout, vectors and algorithms, std::string, STL containers, classes and templates.","topics":[{"id":"ppio","title":"Streams and Basics","desc":"cin/cout, auto, references, ranges and basic control flow","items":[{"id":"cpp-ppio-01","title":"Sum With cin","level":"Easy","statement":"Read two integers with cin and print the sum with cout.","input":"two integers.","output":"the sum.","samples":[{"in":"3 4\n","out":"7"}],"tests":[{"in":"3 4\n","out":"7"},{"in":"-608\n435\n","out":"-173"},{"in":"-79\n433\n","out":"354"},{"in":"556\n-470\n","out":"86"},{"in":"-758\n276\n","out":"-482"},{"in":"-187\n890\n","out":"703"},{"in":"-896\n-786\n","out":"-1682"}]},{"id":"cpp-ppio-02","title":"Setprecision Output","level":"Easy","statement":"Print the number with fixed and setprecision(2).","input":"a real number.","output":"two decimals.","samples":[{"in":"3.14159\n","out":"3.14"}],"tests":[{"in":"3.14159\n","out":"3.14"},{"in":"55.6131\n","out":"55.61"},{"in":"-92.2947\n","out":"-92.29"},{"in":"36.857\n","out":"36.86"},{"in":"75.1148\n","out":"75.11"},{"in":"-26.87\n","out":"-26.87"},{"in":"-2.4668\n","out":"-2.47"}]},{"id":"cpp-ppio-03","title":"Min Of Three Using std::min","level":"Easy","statement":"Print the smallest of three ints using std::min.","input":"three integers.","output":"the minimum.","samples":[{"in":"3 1 2\n","out":"1"}],"tests":[{"in":"3 1 2\n","out":"1"},{"in":"-29 9 -20\n","out":"-29"},{"in":"37 -36 -33\n","out":"-36"},{"in":"27 -9 -36\n","out":"-36"},{"in":"7 26 -47\n","out":"-47"},{"in":"-1 50 -9\n","out":"-9"},{"in":"-40 32 -1\n","out":"-40"}]},{"id":"cpp-ppio-04","title":"Swap With std::swap","level":"Easy","statement":"Swap a and b with std::swap and print \"a b\".","input":"a b.","output":"swapped pair.","samples":[{"in":"1 2\n","out":"2 1"}],"tests":[{"in":"1 2\n","out":"2 1"},{"in":"-11\n-35\n","out":"-35 -11"},{"in":"-19\n32\n","out":"32 -19"},{"in":"7\n-37\n","out":"-37 7"},{"in":"13\n11\n","out":"11 13"},{"in":"-5\n41\n","out":"41 -5"},{"in":"-11\n-37\n","out":"-37 -11"}]},{"id":"cpp-ppio-05","title":"Range For Sum","level":"Easy","statement":"Read N numbers and sum them with a range-based for loop.","input":"N, then N integers.","output":"the sum.","samples":[{"in":"3\n1 2 3\n","out":"6"}],"tests":[{"in":"3\n1 2 3\n","out":"6"},{"in":"3\n18 2 -9\n","out":"11"},{"in":"6\n14 2 7 12 18 6\n","out":"59"},{"in":"6\n4 6 7 9 11 -3\n","out":"34"},{"in":"6\n6 0 10 11 20 -6\n","out":"41"},{"in":"2\n13 1\n","out":"14"},{"in":"7\n9 20 13 -5 -7 8 14\n","out":"52"}]},{"id":"cpp-ppio-06","title":"Boolean Output","level":"Easy","statement":"Print \"true\" or \"false\" for whether N is even (use boolalpha).","input":"N.","output":"true/false.","samples":[{"in":"4\n","out":"true"}],"tests":[{"in":"4\n","out":"true"},{"in":"29\n","out":"false"},{"in":"15\n","out":"false"},{"in":"43\n","out":"false"},{"in":"42\n","out":"true"},{"in":"-33\n","out":"false"},{"in":"44\n","out":"true"}]},{"id":"cpp-ppio-07","title":"Reference Increment","level":"Easy","statement":"Write void inc(int &x) and print x+1 after calling it.","input":"x.","output":"x+1.","samples":[{"in":"5\n","out":"6"}],"tests":[{"in":"5\n","out":"6"},{"in":"-68\n","out":"-67"},{"in":"91\n","out":"92"},{"in":"89\n","out":"90"},{"in":"97\n","out":"98"},{"in":"92\n","out":"93"},{"in":"-32\n","out":"-31"}]},{"id":"cpp-ppio-08","title":"Read Until EOF","level":"Medium","statement":"Read integers until end of input and print their count and sum.","input":"any number of integers on lines.","output":"\"count sum\".","samples":[{"in":"1 2\n3\n","out":"3 6"}],"tests":[{"in":"1 2\n3\n","out":"3 6"},{"in":"-5\n-6\n-1 -6 7 3\n","out":"6 -8"},{"in":"-2 9 3 -9\n-4 -2 4\n","out":"7 -1"},{"in":"-6 3 3\n","out":"3 0"},{"in":"7 -8 -1 7\n1 -3\n-1\n","out":"7 2"},{"in":"-9 -7 -2 -1\n","out":"4 -19"},{"in":"4\n-5\n-1 6\n","out":"4 4"}]},{"id":"cpp-ppio-09","title":"getline Whole Line","level":"Medium","statement":"Read a full line with getline and print the number of characters including spaces.","input":"a line.","output":"length.","samples":[{"in":"hello world\n","out":"11"}],"tests":[{"in":"hello world\n","out":"11"},{"in":"cabcb\n","out":"5"},{"in":"b a\n","out":"3"},{"in":"bbab ac\n","out":"7"},{"in":"c   abbcbbab c\n","out":"14"},{"in":"cb\n","out":"2"},{"in":"ba  a  a\n","out":"8"}]},{"id":"cpp-ppio-10","title":"Constexpr Factorial","level":"Medium","statement":"Compute N! (N<=20) with a constexpr or loop and long long.","input":"N.","output":"N!.","samples":[{"in":"10\n","out":"3628800"}],"tests":[{"in":"10\n","out":"3628800"},{"in":"12\n","out":"479001600"},{"in":"2\n","out":"2"},{"in":"0\n","out":"1"},{"in":"3\n","out":"6"},{"in":"1\n","out":"1"},{"in":"13\n","out":"6227020800"}]},{"id":"cpp-ppio-11","title":"Structured Binding Pair","level":"Medium","statement":"Read pairs and print the one with the larger second value (first on tie) as \"a b\".","input":"N, then N lines \"a b\".","output":"the pair.","samples":[{"in":"2\n1 5\n2 9\n","out":"2 9"}],"tests":[{"in":"2\n1 5\n2 9\n","out":"2 9"},{"in":"4\n5 1\n8 9\n8 8\n5 0\n","out":"8 9"},{"in":"4\n8 9\n4 5\n9 3\n1 9\n","out":"8 9"},{"in":"4\n0 0\n0 1\n7 4\n0 5\n","out":"0 5"},{"in":"4\n6 3\n6 0\n8 3\n3 0\n","out":"6 3"},{"in":"4\n8 7\n8 2\n1 9\n5 9\n","out":"1 9"},{"in":"4\n5 5\n4 6\n1 7\n8 4\n","out":"1 7"}]},{"id":"cpp-ppio-12","title":"Ternary FizzBuzz","level":"Medium","statement":"Print numbers 1..N replacing multiples of 3 with Fizz, 5 with Buzz, both with FizzBuzz.","input":"N.","output":"N lines.","samples":[{"in":"5\n","out":"1\n2\nFizz\n4\nBuzz"}],"tests":[{"in":"5\n","out":"1\n2\nFizz\n4\nBuzz"},{"in":"14\n","out":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz\n11\nFizz\n13\n14"},{"in":"10\n","out":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz"},{"in":"9\n","out":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz"},{"in":"26\n","out":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz\n11\nFizz\n13\n14\nFizzBuzz\n16\n17\nFizz\n19\nBuzz\nFizz\n22\n23\nFizz\nBuzz\n26"},{"in":"16\n","out":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz\n11\nFizz\n13\n14\nFizzBuzz\n16"},{"in":"17\n","out":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz\n11\nFizz\n13\n14\nFizzBuzz\n16\n17"}]},{"id":"cpp-ppio-13","title":"Digit Reverse Palindrome","level":"Medium","statement":"Print YES if N reads the same reversed.","input":"N (non-negative).","output":"YES/NO.","samples":[{"in":"121\n","out":"YES"}],"tests":[{"in":"121\n","out":"YES"},{"in":"4224\n","out":"YES"},{"in":"3663\n","out":"YES"},{"in":"457\n","out":"NO"},{"in":"7997\n","out":"YES"},{"in":"957\n","out":"NO"},{"in":"474\n","out":"YES"}]},{"id":"cpp-ppio-14","title":"Overflow With long long","level":"Medium","statement":"Print a*b where both are up to 10^9.","input":"a b.","output":"product.","samples":[{"in":"1000000000 999999999\n","out":"999999999000000000"}],"tests":[{"in":"1000000000 999999999\n","out":"999999999000000000"},{"in":"979297914 600097401\n","out":"587674132996121514"},{"in":"428485628 237604099\n","out":"101809941575389172"},{"in":"921810750 197803140\n","out":"182337060835755000"},{"in":"774051023 991495156\n","out":"767467839801344588"},{"in":"110389314 73612040\n","out":"8125982597740560"},{"in":"596320169 328968429\n","out":"196170509176944501"}]},{"id":"cpp-ppio-15","title":"Prime Factors","level":"Medium","statement":"Print the prime factors of N in ascending order with repetition.","input":"N>=2.","output":"factors.","samples":[{"in":"12\n","out":"2 2 3"}],"tests":[{"in":"12\n","out":"2 2 3"},{"in":"1201\n","out":"1201"},{"in":"3514\n","out":"2 7 251"},{"in":"4361\n","out":"7 7 89"},{"in":"374\n","out":"2 11 17"},{"in":"674\n","out":"2 337"},{"in":"555\n","out":"3 5 37"}]},{"id":"cpp-ppio-16","title":"Modular Exponent","level":"Hard","statement":"Print a^b mod m using fast exponentiation.","input":"a b m.","output":"result.","samples":[{"in":"2 10 1000\n","out":"24"}],"tests":[{"in":"2 10 1000\n","out":"24"},{"in":"630183 365846296 947877187\n","out":"925978724"},{"in":"225436 361465070 642301731\n","out":"616618078"},{"in":"99473 657470209 886679087\n","out":"689502481"},{"in":"788302 594658679 39050146\n","out":"17633070"},{"in":"553800 543572718 771915403\n","out":"493434390"},{"in":"544504 538995427 58688824\n","out":"45145512"}]},{"id":"cpp-ppio-17","title":"nCr Mod Prime","level":"Hard","statement":"Print C(n, r) mod 1000000007 for n up to 1000.","input":"n r.","output":"result.","samples":[{"in":"5 2\n","out":"10"}],"tests":[{"in":"5 2\n","out":"10"},{"in":"79 12\n","out":"646293792"},{"in":"87 60\n","out":"609581466"},{"in":"627 11\n","out":"148892824"},{"in":"927 608\n","out":"980206623"},{"in":"619 1\n","out":"619"},{"in":"952 722\n","out":"257379983"}]},{"id":"cpp-ppio-18","title":"Sum Of Divisors Sieve","level":"Hard","statement":"Print the sum of divisor-sums sigma(1..N) using a sieve.","input":"N.","output":"total.","samples":[{"in":"5\n","out":"21"}],"tests":[{"in":"5\n","out":"21"},{"in":"596\n","out":"292461"},{"in":"74\n","out":"4520"},{"in":"453\n","out":"168872"},{"in":"584\n","out":"280665"},{"in":"298\n","out":"73105"},{"in":"341\n","out":"95663"}]},{"id":"cpp-ppio-19","title":"Segmented Prime Count","level":"Hard","statement":"Count primes in [L, R].","input":"L R.","output":"count.","samples":[{"in":"10 30\n","out":"6"}],"tests":[{"in":"10 30\n","out":"6"},{"in":"75 1220\n","out":"178"},{"in":"1621 4273\n","out":"331"},{"in":"4739 7016\n","out":"263"},{"in":"1365 3783\n","out":"308"},{"in":"349 2162\n","out":"257"},{"in":"3219 4070\n","out":"105"}]},{"id":"cpp-ppio-20","title":"Josephus Last Survivor","level":"Hard","statement":"N people, every K-th removed; print the last survivor (1-based).","input":"N K.","output":"survivor.","samples":[{"in":"7 3\n","out":"4"}],"tests":[{"in":"7 3\n","out":"4"},{"in":"48 4\n","out":"39"},{"in":"24 6\n","out":"23"},{"in":"24 1\n","out":"24"},{"in":"2 9\n","out":"2"},{"in":"60 6\n","out":"53"},{"in":"31 5\n","out":"8"}]}]},{"id":"pvec","title":"Vectors and Algorithms","desc":"std::vector, sort, lower_bound, accumulate, unique, reverse and lambdas","items":[{"id":"cpp-pvec-01","title":"Vector Sum","level":"Easy","statement":"Push_back N numbers into a vector and print the sum.","input":"N, then N integers.","output":"sum.","samples":[{"in":"3\n1 2 3\n","out":"6"}],"tests":[{"in":"3\n1 2 3\n","out":"6"},{"in":"2\n-9 -7\n","out":"-16"},{"in":"4\n-3 7 2 17\n","out":"23"},{"in":"3\n15 -6 7\n","out":"16"},{"in":"5\n13 12 -4 5 9\n","out":"35"},{"in":"8\n-5 -7 17 1 -6 6 -3 0\n","out":"3"},{"in":"5\n11 16 12 15 7\n","out":"61"}]},{"id":"cpp-pvec-02","title":"Sort Vector","level":"Easy","statement":"sort() the vector and print it.","input":"N, then N integers.","output":"sorted.","samples":[{"in":"3\n3 1 2\n","out":"1 2 3"}],"tests":[{"in":"3\n3 1 2\n","out":"1 2 3"},{"in":"10\n0 6 5 7 16 7 6 13 14 18\n","out":"0 5 6 6 7 7 13 14 16 18"},{"in":"10\n9 -8 -3 9 -3 10 20 -7 -4 14\n","out":"-8 -7 -4 -3 -3 9 9 10 14 20"},{"in":"7\n17 7 -5 -3 -8 -6 1\n","out":"-8 -6 -5 -3 1 7 17"},{"in":"7\n8 8 5 11 18 12 -6\n","out":"-6 5 8 8 11 12 18"},{"in":"8\n-9 13 -8 9 16 18 11 9\n","out":"-9 -8 9 9 11 13 16 18"},{"in":"5\n13 4 15 -6 10\n","out":"-6 4 10 13 15"}]},{"id":"cpp-pvec-03","title":"Sort Descending","level":"Easy","statement":"Use sort with greater<int>().","input":"N, then N integers.","output":"descending.","samples":[{"in":"3\n1 3 2\n","out":"3 2 1"}],"tests":[{"in":"3\n1 3 2\n","out":"3 2 1"},{"in":"5\n16 -6 7 19 -6\n","out":"19 16 7 -6 -6"},{"in":"4\n7 15 6 -6\n","out":"15 7 6 -6"},{"in":"6\n-6 20 -2 12 9 -4\n","out":"20 12 9 -2 -4 -6"},{"in":"8\n18 17 -1 -2 -9 18 2 -6\n","out":"18 18 17 2 -1 -2 -6 -9"},{"in":"4\n10 1 -2 7\n","out":"10 7 1 -2"},{"in":"3\n19 -8 14\n","out":"19 14 -8"}]},{"id":"cpp-pvec-04","title":"Reverse With std::reverse","level":"Easy","statement":"Reverse the vector.","input":"N, then N integers.","output":"reversed.","samples":[{"in":"3\n1 2 3\n","out":"3 2 1"}],"tests":[{"in":"3\n1 2 3\n","out":"3 2 1"},{"in":"5\n-3 16 14 13 13\n","out":"13 13 14 16 -3"},{"in":"9\n3 -9 11 -9 13 10 1 15 6\n","out":"6 15 1 10 13 -9 11 -9 3"},{"in":"2\n-4 17\n","out":"17 -4"},{"in":"2\n-1 19\n","out":"19 -1"},{"in":"9\n-5 2 9 -3 -1 2 19 4 0\n","out":"0 4 19 2 -1 -3 9 2 -5"},{"in":"2\n3 5\n","out":"5 3"}]},{"id":"cpp-pvec-05","title":"Min Max Element","level":"Easy","statement":"Use min_element and max_element.","input":"N, then N integers.","output":"\"min max\".","samples":[{"in":"3\n4 9 2\n","out":"2 9"}],"tests":[{"in":"3\n4 9 2\n","out":"2 9"},{"in":"10\n3 20 12 -8 17 15 -2 -5 -1 -6\n","out":"-8 20"},{"in":"2\n7 -8\n","out":"-8 7"},{"in":"9\n-4 -1 4 0 -5 -9 1 -9 6\n","out":"-9 6"},{"in":"5\n13 18 4 16 14\n","out":"4 18"},{"in":"8\n14 10 -5 -4 17 1 4 9\n","out":"-5 17"},{"in":"3\n11 -8 5\n","out":"-8 11"}]},{"id":"cpp-pvec-06","title":"Count Value","level":"Easy","statement":"Use std::count to count X.","input":"N, list, X.","output":"count.","samples":[{"in":"4\n1 2 1 3\n1\n","out":"2"}],"tests":[{"in":"4\n1 2 1 3\n1\n","out":"2"},{"in":"5\n4 2 1 0 1\n2\n","out":"1"},{"in":"4\n1 4 3 0\n3\n","out":"1"},{"in":"4\n1 2 1 0\n1\n","out":"2"},{"in":"3\n2 3 3\n3\n","out":"2"},{"in":"6\n2 4 3 0 1 2\n3\n","out":"1"},{"in":"1\n0\n1\n","out":"0"}]},{"id":"cpp-pvec-07","title":"Unique After Sort","level":"Easy","statement":"sort then unique to print distinct values ascending.","input":"N, then N integers.","output":"distinct sorted.","samples":[{"in":"4\n3 1 3 2\n","out":"1 2 3"}],"tests":[{"in":"4\n3 1 3 2\n","out":"1 2 3"},{"in":"1\n3\n","out":"3"},{"in":"4\n1 6 0 0\n","out":"0 1 6"},{"in":"12\n6 3 4 5 6 4 1 6 0 4 3 6\n","out":"0 1 3 4 5 6"},{"in":"4\n6 2 0 4\n","out":"0 2 4 6"},{"in":"2\n2 2\n","out":"2"},{"in":"8\n0 4 2 5 5 0 4 4\n","out":"0 2 4 5"}]},{"id":"cpp-pvec-08","title":"Lower Bound Position","level":"Medium","statement":"Sorted vector: print lower_bound index of X (index of first element >= X, N if none).","input":"N, sorted list, X.","output":"index.","samples":[{"in":"4\n1 3 5 7\n4\n","out":"2"}],"tests":[{"in":"4\n1 3 5 7\n4\n","out":"2"},{"in":"4\n8 12 18 29\n26\n","out":"3"},{"in":"8\n0 4 8 12 20 26 27 28\n26\n","out":"5"},{"in":"8\n2 3 7 9 14 15 25 28\n16\n","out":"6"},{"in":"7\n0 1 2 3 7 8 25\n8\n","out":"5"},{"in":"4\n5 8 12 27\n5\n","out":"0"},{"in":"6\n4 10 18 20 22 24\n13\n","out":"2"}]},{"id":"cpp-pvec-09","title":"Partial Sums Vector","level":"Medium","statement":"Print prefix sums using partial_sum.","input":"N, then N integers.","output":"prefix sums.","samples":[{"in":"3\n1 2 3\n","out":"1 3 6"}],"tests":[{"in":"3\n1 2 3\n","out":"1 3 6"},{"in":"5\n15 17 -4 -8 19\n","out":"15 32 28 20 39"},{"in":"1\n20\n","out":"20"},{"in":"1\n-4\n","out":"-4"},{"in":"9\n17 -2 20 8 13 -4 6 15 10\n","out":"17 15 35 43 56 52 58 73 83"},{"in":"2\n12 8\n","out":"12 20"},{"in":"9\n1 6 20 14 -8 7 8 4 1\n","out":"1 7 27 41 33 40 48 52 53"}]},{"id":"cpp-pvec-10","title":"Sort Pairs By Second","level":"Medium","statement":"Sort \"a b\" pairs by b ascending then a ascending using a lambda.","input":"N, then N lines.","output":"sorted pairs.","samples":[{"in":"3\n1 5\n2 3\n0 5\n","out":"2 3\n0 5\n1 5"}],"tests":[{"in":"3\n1 5\n2 3\n0 5\n","out":"2 3\n0 5\n1 5"},{"in":"5\n2 2\n1 3\n1 1\n4 0\n1 0\n","out":"1 0\n4 0\n1 1\n2 2\n1 3"},{"in":"5\n1 0\n4 3\n4 3\n4 4\n3 2\n","out":"1 0\n3 2\n4 3\n4 3\n4 4"},{"in":"5\n4 2\n1 0\n4 3\n1 2\n2 0\n","out":"1 0\n2 0\n1 2\n4 2\n4 3"},{"in":"5\n0 4\n1 4\n3 1\n4 2\n1 1\n","out":"1 1\n3 1\n4 2\n0 4\n1 4"},{"in":"5\n4 1\n1 3\n4 0\n4 3\n0 0\n","out":"0 0\n4 0\n4 1\n1 3\n4 3"},{"in":"5\n3 1\n4 3\n2 1\n1 3\n1 1\n","out":"1 1\n2 1\n3 1\n1 3\n4 3"}]},{"id":"cpp-pvec-11","title":"Remove If Even","level":"Medium","statement":"Erase all even numbers using remove_if; print the rest or NONE.","input":"N, then N integers.","output":"odds.","samples":[{"in":"4\n1 2 3 4\n","out":"1 3"}],"tests":[{"in":"4\n1 2 3 4\n","out":"1 3"},{"in":"3\n5 16 -6\n","out":"5"},{"in":"3\n-8 10 16\n","out":"NONE"},{"in":"5\n15 -8 -3 19 -5\n","out":"15 -3 19 -5"},{"in":"6\n10 -5 8 -2 16 10\n","out":"-5"},{"in":"5\n12 9 2 5 12\n","out":"9 5"},{"in":"5\n14 2 16 -5 11\n","out":"-5 11"}]},{"id":"cpp-pvec-12","title":"Next Permutation","level":"Medium","statement":"Print the next lexicographic permutation of the digits array, or the smallest if it is the last.","input":"N, then N distinct integers.","output":"permutation.","samples":[{"in":"3\n1 2 3\n","out":"1 3 2"}],"tests":[{"in":"3\n1 2 3\n","out":"1 3 2"},{"in":"1\n1\n","out":"1"},{"in":"5\n5 0 2 8 7\n","out":"5 0 7 2 8"},{"in":"6\n0 1 8 6 4 3\n","out":"0 3 1 4 6 8"},{"in":"4\n6 3 5 4\n","out":"6 4 3 5"},{"in":"5\n4 3 5 7 6\n","out":"4 3 6 5 7"},{"in":"1\n4\n","out":"4"}]},{"id":"cpp-pvec-13","title":"Two Pointer Pair Sum","level":"Medium","statement":"Sorted array: print YES if two elements sum to K.","input":"N, sorted list, K.","output":"YES/NO.","samples":[{"in":"4\n1 2 4 7\n9\n","out":"YES"}],"tests":[{"in":"4\n1 2 4 7\n9\n","out":"YES"},{"in":"5\n4 4 7 15 17\n29\n","out":"NO"},{"in":"7\n0 3 6 10 13 17 18\n28\n","out":"YES"},{"in":"6\n3 5 7 10 15 19\n30\n","out":"NO"},{"in":"6\n0 2 7 7 8 11\n23\n","out":"NO"},{"in":"2\n4 5\n4\n","out":"NO"},{"in":"3\n7 19 20\n34\n","out":"NO"}]},{"id":"cpp-pvec-14","title":"Rotate With std::rotate","level":"Medium","statement":"Rotate the vector left by K.","input":"N, list, K.","output":"rotated.","samples":[{"in":"5\n1 2 3 4 5\n2\n","out":"3 4 5 1 2"}],"tests":[{"in":"5\n1 2 3 4 5\n2\n","out":"3 4 5 1 2"},{"in":"1\n1\n6\n","out":"1"},{"in":"3\n5 5 5\n10\n","out":"5 5 5"},{"in":"6\n4 2 1 9 1 0\n1\n","out":"2 1 9 1 0 4"},{"in":"2\n1 1\n14\n","out":"1 1"},{"in":"7\n7 7 9 8 8 9 1\n0\n","out":"7 7 9 8 8 9 1"},{"in":"7\n8 2 5 3 0 2 3\n14\n","out":"8 2 5 3 0 2 3"}]},{"id":"cpp-pvec-15","title":"Median","level":"Medium","statement":"Print the median (average of two middles with one decimal when N is even, else the middle as x.0).","input":"N, then N integers.","output":"median.","samples":[{"in":"4\n1 2 3 4\n","out":"2.5"}],"tests":[{"in":"4\n1 2 3 4\n","out":"2.5"},{"in":"10\n-7 -7 -2 1 7 13 6 6 2 16\n","out":"4.0"},{"in":"4\n-8 0 14 11\n","out":"5.5"},{"in":"9\n1 -1 17 -9 -6 11 1 19 20\n","out":"1.0"},{"in":"10\n10 3 -4 -5 1 14 4 16 -8 9\n","out":"3.5"},{"in":"6\n4 3 19 -9 6 -5\n","out":"3.5"},{"in":"9\n11 9 10 14 1 16 7 -1 -3\n","out":"9.0"}]},{"id":"cpp-pvec-16","title":"Longest Increasing Subsequence","level":"Hard","statement":"Print the LIS length (strict).","input":"N, then N integers.","output":"length.","samples":[{"in":"6\n10 9 2 5 3 7\n","out":"3"}],"tests":[{"in":"6\n10 9 2 5 3 7\n","out":"3"},{"in":"4\n3 16 14 2\n","out":"2"},{"in":"2\n13 6\n","out":"1"},{"in":"5\n11 9 6 19 6\n","out":"2"},{"in":"5\n11 5 10 17 20\n","out":"4"},{"in":"9\n13 18 8 14 1 14 15 19 12\n","out":"4"},{"in":"12\n11 13 15 15 13 11 1 2 16 10 8 3\n","out":"4"}]},{"id":"cpp-pvec-17","title":"Next Greater Element","level":"Hard","statement":"For each element print the next greater element to its right or -1.","input":"N, then N integers.","output":"N numbers.","samples":[{"in":"4\n4 5 2 25\n","out":"5 25 25 -1"}],"tests":[{"in":"4\n4 5 2 25\n","out":"5 25 25 -1"},{"in":"7\n13 0 4 20 5 19 20\n","out":"20 4 20 -1 19 20 -1"},{"in":"9\n2 12 9 10 18 20 2 17 19\n","out":"12 18 10 18 20 -1 17 19 -1"},{"in":"9\n14 10 11 20 17 0 19 2 18\n","out":"20 11 20 -1 19 19 -1 18 -1"},{"in":"3\n11 10 16\n","out":"16 16 -1"},{"in":"3\n12 15 7\n","out":"15 -1 -1"},{"in":"4\n5 7 20 16\n","out":"7 20 -1 -1"}]},{"id":"cpp-pvec-18","title":"Count Inversions","level":"Hard","statement":"Count pairs i<j with a[i]>a[j].","input":"N, then N integers.","output":"count.","samples":[{"in":"4\n3 1 2 0\n","out":"5"}],"tests":[{"in":"4\n3 1 2 0\n","out":"5"},{"in":"6\n2 5 0 17 15 3\n","out":"6"},{"in":"11\n1 2 9 12 19 6 11 20 17 15 9\n","out":"16"},{"in":"10\n9 8 14 0 8 8 8 11 7 11\n","out":"19"},{"in":"7\n16 14 15 14 4 8 5\n","out":"17"},{"in":"7\n13 10 6 15 20 20 13\n","out":"6"},{"in":"7\n15 19 7 18 15 2 20\n","out":"10"}]},{"id":"cpp-pvec-19","title":"Merge Overlapping Intervals","level":"Hard","statement":"Merge overlapping intervals (touching merge).","input":"N, then N lines \"a b\".","output":"merged one per line.","samples":[{"in":"3\n1 3\n2 6\n8 10\n","out":"1 6\n8 10"}],"tests":[{"in":"3\n1 3\n2 6\n8 10\n","out":"1 6\n8 10"},{"in":"5\n6 9\n2 5\n12 12\n2 6\n15 20\n","out":"2 9\n12 12\n15 20"},{"in":"5\n3 5\n7 10\n15 15\n2 3\n3 4\n","out":"2 5\n7 10\n15 15"},{"in":"5\n4 8\n3 3\n5 7\n12 13\n9 13\n","out":"3 3\n4 8\n9 13"},{"in":"5\n11 12\n9 14\n5 10\n12 16\n9 11\n","out":"5 16"},{"in":"5\n14 14\n4 5\n6 7\n14 14\n4 9\n","out":"4 9\n14 14"},{"in":"5\n11 13\n10 13\n15 15\n12 17\n0 0\n","out":"0 0\n10 17"}]},{"id":"cpp-pvec-20","title":"Longest Consecutive Run","level":"Hard","statement":"Print the length of the longest run of consecutive integers (as a set).","input":"N, then N integers.","output":"length.","samples":[{"in":"6\n100 4 200 1 3 2\n","out":"4"}],"tests":[{"in":"6\n100 4 200 1 3 2\n","out":"4"},{"in":"1\n7\n","out":"1"},{"in":"9\n3 10 11 12 4 10 15 3 14\n","out":"3"},{"in":"9\n1 10 6 10 0 3 14 5 8\n","out":"2"},{"in":"8\n13 15 11 12 13 8 1 1\n","out":"3"},{"in":"12\n1 11 2 6 11 10 3 1 12 6 15 3\n","out":"3"},{"in":"4\n3 10 15 8\n","out":"1"}]},{"id":"cpp-pvec-21","title":"Maximum Product Subarray","level":"Hard","statement":"Print the maximum product of a contiguous subarray.","input":"N, then N integers.","output":"product.","samples":[{"in":"4\n2 3 -2 4\n","out":"6"}],"tests":[{"in":"4\n2 3 -2 4\n","out":"6"},{"in":"7\n-1 2 0 0 -4 0 -3\n","out":"2"},{"in":"3\n-2 4 4\n","out":"16"},{"in":"2\n1 0\n","out":"1"},{"in":"1\n-4\n","out":"-4"},{"in":"3\n-1 -2 3\n","out":"6"},{"in":"8\n-4 -2 -1 2 4 4 -1 0\n","out":"256"}]},{"id":"cpp-pvec-22","title":"K Closest To Target","level":"Hard","statement":"Print the K elements closest to T (ties: smaller value first), sorted ascending.","input":"N, list, T, K.","output":"K values.","samples":[{"in":"5\n1 2 3 4 5\n3\n2\n","out":"2 3"}],"tests":[{"in":"5\n1 2 3 4 5\n3\n2\n","out":"2 3"},{"in":"9\n4 0 7 0 6 13 3 5 4\n17\n4\n","out":"5 6 7 13"},{"in":"5\n7 6 15 14 18\n14\n2\n","out":"14 15"},{"in":"3\n5 10 11\n16\n3\n","out":"5 10 11"},{"in":"5\n12 2 1 1 15\n14\n2\n","out":"12 15"},{"in":"6\n2 5 15 10 6 3\n4\n4\n","out":"2 3 5 6"},{"in":"9\n2 19 9 4 4 17 17 3 6\n20\n8\n","out":"3 4 4 6 9 17 17 19"}]}]},{"id":"pstr","title":"std::string and Streams","desc":"string methods, find, substr, stringstream and character functions","items":[{"id":"cpp-pstr-01","title":"String Size And Append","level":"Easy","statement":"Concatenate two words with + and print the result and its size.","input":"two words.","output":"\"text size\".","samples":[{"in":"ab\ncd\n","out":"abcd 4"}],"tests":[{"in":"ab\ncd\n","out":"abcd 4"},{"in":"a\ncacbb\n","out":"acacbb 6"},{"in":"bcabb\nbcbcb\n","out":"bcabbbcbcb 10"},{"in":"aca\naaab\n","out":"acaaaab 7"},{"in":"abc\na\n","out":"abca 4"},{"in":"ca\nacbb\n","out":"caacbb 6"},{"in":"ccc\nca\n","out":"cccca 5"}]},{"id":"cpp-pstr-02","title":"Reverse String","level":"Easy","statement":"Use std::reverse on the word.","input":"a word.","output":"reversed.","samples":[{"in":"abc\n","out":"cba"}],"tests":[{"in":"abc\n","out":"cba"},{"in":"zzbzaza\n","out":"azazbzz"},{"in":"ybbybbbcz\n","out":"zcbbbybby"},{"in":"yzczbcxax\n","out":"xaxcbzczy"},{"in":"xac\n","out":"cax"},{"in":"caazzyzba\n","out":"abzyzzaac"},{"in":"ayybzyx\n","out":"xyzbyya"}]},{"id":"cpp-pstr-03","title":"Substr Middle","level":"Easy","statement":"Print substr(1, len-2) of the word (empty line if len<=2).","input":"a word.","output":"the middle.","samples":[{"in":"hello\n","out":"ell"}],"tests":[{"in":"hello\n","out":"ell"},{"in":"yzbxbbc\n","out":"zbxbb"},{"in":"b\n","out":""},{"in":"azzazx\n","out":"zzaz"},{"in":"zy\n","out":""},{"in":"baybzayy\n","out":"aybzay"},{"in":"zxycbcbc\n","out":"xycbcb"}]},{"id":"cpp-pstr-04","title":"Find Character","level":"Easy","statement":"Print find() result or -1 for the letter in the word.","input":"word then letter.","output":"index.","samples":[{"in":"hello\nl\n","out":"2"}],"tests":[{"in":"hello\nl\n","out":"2"},{"in":"baddd\nc\n","out":"-1"},{"in":"cdadacb\nc\n","out":"0"},{"in":"dccbc\ne\n","out":"-1"},{"in":"acadbbb\nb\n","out":"4"},{"in":"baacb\nc\n","out":"3"},{"in":"aacad\nc\n","out":"2"}]},{"id":"cpp-pstr-05","title":"To Lower Using transform","level":"Easy","statement":"Lower-case the line.","input":"a line.","output":"lowered.","samples":[{"in":"Hello World\n","out":"hello world"}],"tests":[{"in":"Hello World\n","out":"hello world"},{"in":"a D\n","out":"a d"},{"in":"acccBc  cD\n","out":"acccbc  cd"},{"in":"DB\n","out":"db"},{"in":"caBac\n","out":"cabac"},{"in":"caBBcaB\n","out":"cabbcab"},{"in":"DDccaBc\n","out":"ddccabc"}]},{"id":"cpp-pstr-06","title":"Compare Strings","level":"Easy","statement":"Print SAME or DIFFERENT.","input":"two words.","output":"verdict.","samples":[{"in":"a\nb\n","out":"DIFFERENT"}],"tests":[{"in":"a\nb\n","out":"DIFFERENT"},{"in":"aa\na\n","out":"DIFFERENT"},{"in":"aa\naa\n","out":"SAME"},{"in":"bb\nab\n","out":"DIFFERENT"},{"in":"b\nba\n","out":"DIFFERENT"},{"in":"b\nab\n","out":"DIFFERENT"},{"in":"aa\nba\n","out":"DIFFERENT"}]},{"id":"cpp-pstr-07","title":"Count Spaces","level":"Easy","statement":"Count the spaces in the line.","input":"a line.","output":"count.","samples":[{"in":"a b c\n","out":"2"}],"tests":[{"in":"a b c\n","out":"2"},{"in":"bbbb   a  a\n","out":"5"},{"in":"a      b a\n","out":"7"},{"in":"aaa\n","out":"0"},{"in":"aa\n","out":"0"},{"in":"a a\n","out":"1"},{"in":"b b aa aa\n","out":"3"}]},{"id":"cpp-pstr-08","title":"stringstream Split Sum","level":"Medium","statement":"Split a line of ints with stringstream and print their sum.","input":"a line of integers.","output":"sum.","samples":[{"in":"1 2 3\n","out":"6"}],"tests":[{"in":"1 2 3\n","out":"6"},{"in":"-1 3\n","out":"2"},{"in":"-5 4 7 -5 -5 -1 -7 8\n","out":"-4"},{"in":"0 -8 -6 -6 -6\n","out":"-26"},{"in":"-3 -6 1\n","out":"-8"},{"in":"3 -7 1 -8 -6 -2\n","out":"-19"},{"in":"0 6 3 -8 -9 -2 8 0\n","out":"-2"}]},{"id":"cpp-pstr-09","title":"to_string Concatenate","level":"Medium","statement":"Print all numbers 1..N joined without spaces using to_string.","input":"N.","output":"the text.","samples":[{"in":"12\n","out":"123456789101112"}],"tests":[{"in":"12\n","out":"123456789101112"},{"in":"26\n","out":"1234567891011121314151617181920212223242526"},{"in":"9\n","out":"123456789"},{"in":"7\n","out":"1234567"},{"in":"16\n","out":"12345678910111213141516"},{"in":"18\n","out":"123456789101112131415161718"},{"in":"23\n","out":"1234567891011121314151617181920212223"}]},{"id":"cpp-pstr-10","title":"Replace All","level":"Medium","statement":"Replace every occurrence of the second word with the third in the first line.","input":"text, old, new (words).","output":"new text.","samples":[{"in":"banana\nan\nAN\n","out":"bANANa"}],"tests":[{"in":"banana\nan\nAN\n","out":"bANANa"},{"in":"bbbabb\nb\nX\n","out":"XXXaXX"},{"in":"bababaa\nb\nX\n","out":"XaXaXaa"},{"in":"babaabaabb\nab\nX\n","out":"bXaXaXb"},{"in":"baabaaba\na\nX\n","out":"bXXbXXbX"},{"in":"aabbabaabb\na\nX\n","out":"XXbbXbXXbb"},{"in":"bbabbbb\nba\nX\n","out":"bXbbbb"}]},{"id":"cpp-pstr-11","title":"Palindrome Ignoring Non Letters","level":"Medium","statement":"Print YES if the letters only (case-insensitive) form a palindrome.","input":"a line.","output":"YES/NO.","samples":[{"in":"A man, a plan, a canal: Panama\n","out":"YES"}],"tests":[{"in":"A man, a plan, a canal: Panama\n","out":"YES"},{"in":"ab\n","out":"NO"},{"in":"Was it a car or a cat I saw?\n","out":"YES"},{"in":"abca\n","out":"NO"},{"in":"x\n","out":"YES"},{"in":"abc cba\n","out":"YES"},{"in":"No lemon, no melon\n","out":"YES"}]},{"id":"cpp-pstr-12","title":"Word Frequency Sorted","level":"Medium","statement":"Print each distinct word with its count, words sorted alphabetically, \"word count\" per line.","input":"a line of words.","output":"rows.","samples":[{"in":"b a b\n","out":"a 1\nb 2"}],"tests":[{"in":"b a b\n","out":"a 1\nb 2"},{"in":"cdc cb c dbab ced\n","out":"c 1\ncb 1\ncdc 1\nced 1\ndbab 1"},{"in":"baba acda dd aaed eedb bbac cd deeda\n","out":"aaed 1\nacda 1\nbaba 1\nbbac 1\ncd 1\ndd 1\ndeeda 1\needb 1"},{"in":"bbacd de ccbcd\n","out":"bbacd 1\nccbcd 1\nde 1"},{"in":"bd\n","out":"bd 1"},{"in":"bdad a dcbd ecc\n","out":"a 1\nbdad 1\ndcbd 1\necc 1"},{"in":"ceaa cb abcad ba a e\n","out":"a 1\nabcad 1\nba 1\ncb 1\nceaa 1\ne 1"}]},{"id":"cpp-pstr-13","title":"Capitalize Each Word","level":"Medium","statement":"Upper-case the first letter of each word.","input":"a line of lower-case words.","output":"the line.","samples":[{"in":"hello big world\n","out":"Hello Big World"}],"tests":[{"in":"hello big world\n","out":"Hello Big World"},{"in":"ac ee\n","out":"Ac Ee"},{"in":"b c c dc dc\n","out":"B C C Dc Dc"},{"in":"a cacbe adcad ebcc\n","out":"A Cacbe Adcad Ebcc"},{"in":"a c\n","out":"A C"},{"in":"acad dbbb ad\n","out":"Acad Dbbb Ad"},{"in":"dac ccbe\n","out":"Dac Ccbe"}]},{"id":"cpp-pstr-14","title":"Remove Vowels","level":"Medium","statement":"Delete all vowels from the line.","input":"a line.","output":"result (may be empty).","samples":[{"in":"Hello World\n","out":"Hll Wrld"}],"tests":[{"in":"Hello World\n","out":"Hll Wrld"},{"in":"bbiEEyicOOc\n","out":"bbycc"},{"in":"yxEicccixbcE\n","out":"yxcccxbc"},{"in":"c\n","out":"c"},{"in":"ixaxOa\n","out":"xx"},{"in":"bExbOEcxO x\n","out":"bxbcx x"},{"in":"aybi OE c\n","out":"yb  c"}]},{"id":"cpp-pstr-15","title":"Starts With And Ends With","level":"Medium","statement":"Print YES if the word starts with the first letter-pair of line 2 and ends with line 3.","input":"word, prefix, suffix.","output":"YES/NO.","samples":[{"in":"abcde\nab\nde\n","out":"YES"}],"tests":[{"in":"abcde\nab\nde\n","out":"YES"},{"in":"bbb\naa\nb\n","out":"NO"},{"in":"bbaabb\na\na\n","out":"NO"},{"in":"bab\na\nbb\n","out":"NO"},{"in":"bbba\nba\nb\n","out":"NO"},{"in":"baabab\nb\nbb\n","out":"NO"},{"in":"aa\na\nb\n","out":"NO"}]},{"id":"cpp-pstr-16","title":"Longest Common Prefix Of Words","level":"Hard","statement":"Print the common prefix of all words or NONE.","input":"a line of words.","output":"prefix.","samples":[{"in":"flower flow flight\n","out":"fl"}],"tests":[{"in":"flower flow flight\n","out":"fl"},{"in":"ba baa ab abbab\n","out":"NONE"},{"in":"aabab\n","out":"aabab"},{"in":"ab baaa a aa\n","out":"NONE"},{"in":"b abb bbab a\n","out":"NONE"},{"in":"aabbb abb\n","out":"a"},{"in":"bbabb aaa aab\n","out":"NONE"}]},{"id":"cpp-pstr-17","title":"Group Anagrams","level":"Hard","statement":"Print anagram groups sorted inside and ordered by first word.","input":"a line of words.","output":"groups.","samples":[{"in":"eat tea tan ate nat bat\n","out":"ate eat tea\nbat\nnat tan"}],"tests":[{"in":"eat tea tan ate nat bat\n","out":"ate eat tea\nbat\nnat tan"},{"in":"ba aa\n","out":"aa\nba"},{"in":"ba a aaa a acc b b\n","out":"a\naaa\nacc\nb\nba"},{"in":"ca cbc\n","out":"ca\ncbc"},{"in":"bac b\n","out":"b\nbac"},{"in":"bb cc cb c cc b aab\n","out":"aab\nb\nbb\nc\ncb\ncc"},{"in":"abb bb\n","out":"abb\nbb"}]},{"id":"cpp-pstr-18","title":"Minimum Window Contains","level":"Hard","statement":"Print the length of the shortest substring of text containing all letters of the pattern (with multiplicity), or 0.","input":"text then pattern.","output":"length.","samples":[{"in":"ADOBECODEBANC\nABC\n","out":"4"}],"tests":[{"in":"ADOBECODEBANC\nABC\n","out":"4"},{"in":"ccacbbcaacca\nbcb\n","out":"3"},{"in":"c\nb\n","out":"0"},{"in":"cca\ncb\n","out":"0"},{"in":"bb\nb\n","out":"1"},{"in":"ccacabcaccba\nbc\n","out":"2"},{"in":"cbbaca\naaa\n","out":"0"}]},{"id":"cpp-pstr-19","title":"Decode Ways","level":"Hard","statement":"A=1..Z=26. Count decodings of a digit string.","input":"digits.","output":"count.","samples":[{"in":"226\n","out":"3"}],"tests":[{"in":"226\n","out":"3"},{"in":"3284850\n","out":"0"},{"in":"6268501\n","out":"0"},{"in":"839086405\n","out":"0"},{"in":"63505\n","out":"0"},{"in":"91859\n","out":"2"},{"in":"6\n","out":"1"}]},{"id":"cpp-pstr-20","title":"Expression Evaluate","level":"Hard","statement":"Evaluate +,-,* integer expression without spaces (precedence, no parentheses).","input":"expression.","output":"value.","samples":[{"in":"2+3*4-1\n","out":"13"}],"tests":[{"in":"2+3*4-1\n","out":"13"},{"in":"5-6-7+1*4*9\n","out":"28"},{"in":"7-5+3-6\n","out":"-1"},{"in":"4-5*8+1+2-9\n","out":"-42"},{"in":"3*4+0+5\n","out":"17"},{"in":"3*1\n","out":"3"},{"in":"3*7*4\n","out":"84"}]},{"id":"cpp-pstr-21","title":"Big Factorial Digits Sum","level":"Hard","statement":"Compute N! (N<=100) with a digit vector and print the digit sum.","input":"N.","output":"digit sum.","samples":[{"in":"10\n","out":"27"}],"tests":[{"in":"10\n","out":"27"},{"in":"17\n","out":"63"},{"in":"95\n","out":"585"},{"in":"25\n","out":"72"},{"in":"19\n","out":"45"},{"in":"40\n","out":"189"},{"in":"80\n","out":"450"}]},{"id":"cpp-pstr-22","title":"Roman To Integer","level":"Hard","statement":"Convert a Roman numeral to an integer.","input":"Roman numeral (up to 3999).","output":"value.","samples":[{"in":"MCMXCIV\n","out":"1994"}],"tests":[{"in":"MCMXCIV\n","out":"1994"},{"in":"IV\n","out":"4"},{"in":"LVIII\n","out":"58"},{"in":"IX\n","out":"9"},{"in":"XL\n","out":"40"},{"in":"XIV\n","out":"14"},{"in":"CD\n","out":"400"}]}]},{"id":"pstl","title":"STL Containers","desc":"map, set, stack, queue, deque, priority_queue and pair","items":[{"id":"cpp-pstl-01","title":"Set Size","level":"Easy","statement":"Insert numbers in a std::set and print its size.","input":"N, then N integers.","output":"distinct count.","samples":[{"in":"4\n1 2 2 3\n","out":"3"}],"tests":[{"in":"4\n1 2 2 3\n","out":"3"},{"in":"2\n0 0\n","out":"1"},{"in":"11\n2 0 3 5 5 0 1 2 4 6 2\n","out":"7"},{"in":"8\n2 2 3 1 4 5 6 6\n","out":"6"},{"in":"6\n3 5 5 4 5 2\n","out":"4"},{"in":"5\n5 2 3 6 4\n","out":"5"},{"in":"1\n5\n","out":"1"}]},{"id":"cpp-pstl-02","title":"Map Count Word","level":"Easy","statement":"Count how many times the word in line 2 occurs in line 1.","input":"a line of words, then a word.","output":"count.","samples":[{"in":"a b a\na\n","out":"2"}],"tests":[{"in":"a b a\na\n","out":"2"},{"in":"c c c b c\nb\n","out":"1"},{"in":"b a a b a b\nd\n","out":"0"},{"in":"c b c c c a\nd\n","out":"0"},{"in":"c b b a b a\nc\n","out":"1"},{"in":"a b c b a c b\nb\n","out":"3"},{"in":"c c a\nc\n","out":"2"}]},{"id":"cpp-pstl-03","title":"Stack Reverse","level":"Easy","statement":"Push all and pop all, printing popped order.","input":"N, then N integers.","output":"reversed.","samples":[{"in":"3\n1 2 3\n","out":"3 2 1"}],"tests":[{"in":"3\n1 2 3\n","out":"3 2 1"},{"in":"10\n-4 -5 -1 -6 5 -3 17 20 4 9\n","out":"9 4 20 17 -3 5 -6 -1 -5 -4"},{"in":"3\n16 9 19\n","out":"19 9 16"},{"in":"10\n-8 4 5 9 9 9 -9 -6 14 20\n","out":"20 14 -6 -9 9 9 9 5 4 -8"},{"in":"9\n-7 -6 12 5 -3 11 3 -6 16\n","out":"16 -6 3 11 -3 5 12 -6 -7"},{"in":"1\n1\n","out":"1"},{"in":"6\n16 -7 19 -9 2 9\n","out":"9 2 -9 19 -7 16"}]},{"id":"cpp-pstl-04","title":"Queue Front Back","level":"Easy","statement":"Push all and print front then back.","input":"N, then N integers.","output":"\"front back\".","samples":[{"in":"3\n1 2 3\n","out":"1 3"}],"tests":[{"in":"3\n1 2 3\n","out":"1 3"},{"in":"6\n-2 19 4 -8 12 -7\n","out":"-2 -7"},{"in":"8\n-3 0 -5 -1 6 -4 13 -4\n","out":"-3 -4"},{"in":"6\n-6 2 -6 2 -2 -2\n","out":"-6 -2"},{"in":"4\n1 14 3 16\n","out":"1 16"},{"in":"8\n8 7 18 15 13 17 9 9\n","out":"8 9"},{"in":"10\n2 -7 16 4 19 11 -6 14 13 8\n","out":"2 8"}]},{"id":"cpp-pstl-05","title":"Set Sorted Output","level":"Easy","statement":"Print distinct values in sorted order from a set.","input":"N, then N integers.","output":"values.","samples":[{"in":"4\n3 1 3 2\n","out":"1 2 3"}],"tests":[{"in":"4\n3 1 3 2\n","out":"1 2 3"},{"in":"3\n0 6 3\n","out":"0 3 6"},{"in":"5\n7 8 2 0 0\n","out":"0 2 7 8"},{"in":"7\n8 6 2 4 1 4 6\n","out":"1 2 4 6 8"},{"in":"1\n4\n","out":"4"},{"in":"7\n8 8 8 0 5 3 6\n","out":"0 3 5 6 8"},{"in":"1\n1\n","out":"1"}]},{"id":"cpp-pstl-06","title":"Max Heap Pop","level":"Easy","statement":"Use priority_queue to print the 2 largest values (or all if fewer).","input":"N, then N integers.","output":"up to 2 values.","samples":[{"in":"4\n4 9 1 7\n","out":"9 7"}],"tests":[{"in":"4\n4 9 1 7\n","out":"9 7"},{"in":"9\n8 8 20 -8 -1 13 0 8 3\n","out":"20 13"},{"in":"1\n19\n","out":"19"},{"in":"1\n5\n","out":"5"},{"in":"2\n-1 14\n","out":"14 -1"},{"in":"6\n-3 -1 17 13 2 7\n","out":"17 13"},{"in":"4\n1 10 -5 -7\n","out":"10 1"}]},{"id":"cpp-pstl-07","title":"Pair Compare","level":"Easy","statement":"Read two pairs and print the lexicographically smaller as \"a b\".","input":"two lines \"a b\".","output":"smaller pair.","samples":[{"in":"1 5\n1 3\n","out":"1 3"}],"tests":[{"in":"1 5\n1 3\n","out":"1 3"},{"in":"1 2\n0 2\n","out":"0 2"},{"in":"0 2\n3 2\n","out":"0 2"},{"in":"3 2\n1 2\n","out":"1 2"},{"in":"3 0\n1 3\n","out":"1 3"},{"in":"0 0\n0 3\n","out":"0 0"},{"in":"3 1\n1 1\n","out":"1 1"}]},{"id":"cpp-pstl-08","title":"Frequency Map Ordered","level":"Medium","statement":"Print \"value:count\" ascending by value (map).","input":"N, then N integers.","output":"pairs.","samples":[{"in":"4\n3 1 3 2\n","out":"1:1 2:1 3:2"}],"tests":[{"in":"4\n3 1 3 2\n","out":"1:1 2:1 3:2"},{"in":"4\n1 0 2 1\n","out":"0:1 1:2 2:1"},{"in":"7\n4 2 2 2 0 0 5\n","out":"0:2 2:3 4:1 5:1"},{"in":"12\n1 1 4 0 3 0 1 6 1 5 1 5\n","out":"0:2 1:5 3:1 4:1 5:2 6:1"},{"in":"1\n4\n","out":"4:1"},{"in":"1\n2\n","out":"2:1"},{"in":"11\n0 0 3 5 1 0 5 3 0 3 6\n","out":"0:4 1:1 3:3 5:2 6:1"}]},{"id":"cpp-pstl-09","title":"Min Heap K Smallest","level":"Medium","statement":"Use a min-heap to print the K smallest.","input":"N, list, K.","output":"K values.","samples":[{"in":"5\n5 3 8 1 9\n2\n","out":"1 3"}],"tests":[{"in":"5\n5 3 8 1 9\n2\n","out":"1 3"},{"in":"3\n28 16 0\n2\n","out":"0 16"},{"in":"5\n18 19 10 27 16\n3\n","out":"10 16 18"},{"in":"6\n29 17 28 15 19 26\n5\n","out":"15 17 19 26 28"},{"in":"1\n0\n1\n","out":"0"},{"in":"9\n18 17 25 14 8 1 27 7 8\n8\n","out":"1 7 8 8 14 17 18 25"},{"in":"9\n15 30 9 20 22 25 6 26 26\n8\n","out":"6 9 15 20 22 25 26 26"}]},{"id":"cpp-pstl-10","title":"Deque Sliding Max","level":"Medium","statement":"Window maximum using a deque.","input":"N, list, K.","output":"maxima.","samples":[{"in":"5\n1 3 -1 5 2\n3\n","out":"3 5 5"}],"tests":[{"in":"5\n1 3 -1 5 2\n3\n","out":"3 5 5"},{"in":"8\n-9 -8 -1 0 -7 9 -3 4\n3\n","out":"-1 0 0 9 9 9"},{"in":"1\n6\n1\n","out":"6"},{"in":"9\n7 -4 -9 9 6 7 -3 2 4\n6\n","out":"9 9 9 9"},{"in":"3\n-8 3 7\n1\n","out":"-8 3 7"},{"in":"6\n4 -5 6 -2 -5 3\n5\n","out":"6 6"},{"in":"5\n3 9 0 -9 8\n2\n","out":"9 9 0 8"}]},{"id":"cpp-pstl-11","title":"Balanced Brackets Stack","level":"Medium","statement":"YES if balanced ()[]{}.","input":"a bracket string.","output":"YES/NO.","samples":[{"in":"([]{})\n","out":"YES"}],"tests":[{"in":"([]{})\n","out":"YES"},{"in":"{}(](\n","out":"NO"},{"in":")}{{)[\n","out":"NO"},{"in":"{]}(\n","out":"NO"},{"in":"[[{}\n","out":"NO"},{"in":"{)))[}\n","out":"NO"},{"in":"]}][{\n","out":"NO"}]},{"id":"cpp-pstl-12","title":"Common Elements Sets","level":"Medium","statement":"Print sorted common distinct values or NONE.","input":"two lines \"n values\".","output":"common.","samples":[{"in":"3 1 2 3\n2 2 5\n","out":"2"}],"tests":[{"in":"3 1 2 3\n2 2 5\n","out":"2"},{"in":"5 2 1 1 2 6\n1 1\n","out":"1"},{"in":"1 1\n5 6 5 0 5 6\n","out":"NONE"},{"in":"1 3\n1 1\n","out":"NONE"},{"in":"2 6 2\n1 1\n","out":"NONE"},{"in":"3 5 6 3\n1 1\n","out":"NONE"},{"in":"4 6 5 0 6\n4 0 4 5 4\n","out":"0 5"}]},{"id":"cpp-pstl-13","title":"Multiset Lower Upper","level":"Medium","statement":"Count numbers in [A, B] using a multiset.","input":"N, list, A, B.","output":"count.","samples":[{"in":"4\n1 5 3 7\n2\n6\n","out":"2"}],"tests":[{"in":"4\n1 5 3 7\n2\n6\n","out":"2"},{"in":"7\n13 16 15 3 2 15 1\n14\n17\n","out":"3"},{"in":"7\n20 10 9 10 18 12 2\n2\n2\n","out":"1"},{"in":"8\n11 18 11 11 5 9 4 6\n14\n20\n","out":"1"},{"in":"2\n3 0\n6\n8\n","out":"0"},{"in":"7\n6 19 12 1 14 1 6\n6\n11\n","out":"2"},{"in":"2\n6 13\n2\n3\n","out":"0"}]},{"id":"cpp-pstl-14","title":"Queue Simulation Ticket","level":"Medium","statement":"N people with ticket counts; each round the front buys 1 and re-queues if more needed. Print the finishing order (1-based ids).","input":"N, then N counts.","output":"ids.","samples":[{"in":"3\n2 1 3\n","out":"2 1 3"}],"tests":[{"in":"3\n2 1 3\n","out":"2 1 3"},{"in":"2\n2 1\n","out":"2 1"},{"in":"4\n3 4 2 1\n","out":"4 3 1 2"},{"in":"3\n3 2 2\n","out":"2 3 1"},{"in":"2\n3 4\n","out":"1 2"},{"in":"3\n3 3 2\n","out":"3 1 2"},{"in":"4\n2 1 4 4\n","out":"2 1 3 4"}]},{"id":"cpp-pstl-15","title":"Most Frequent Word","level":"Medium","statement":"Print the most frequent word (alphabetically first on tie).","input":"a line.","output":"the word.","samples":[{"in":"b a b a c\n","out":"a"}],"tests":[{"in":"b a b a c\n","out":"a"},{"in":"e bd eda edea ab cbbad dd\n","out":"ab"},{"in":"add\n","out":"add"},{"in":"abb dbdae ca acdb\n","out":"abb"},{"in":"a ca\n","out":"a"},{"in":"ab ebbd ca eeac\n","out":"ab"},{"in":"daad dae aecc dae ddaa b\n","out":"dae"}]},{"id":"cpp-pstl-16","title":"Dijkstra Shortest Paths","level":"Hard","statement":"Undirected weighted graph; print distances from node 1 to all nodes (-1 unreachable).","input":"N M, then M lines \"a b w\".","output":"N numbers.","samples":[{"in":"3 2\n1 2 4\n2 3 1\n","out":"0 4 5"}],"tests":[{"in":"3 2\n1 2 4\n2 3 1\n","out":"0 4 5"},{"in":"3 1\n1 3 6\n","out":"0 -1 6"},{"in":"6 5\n1 6 9\n4 1 7\n4 3 4\n1 5 1\n5 1 8\n","out":"0 -1 11 7 1 9"},{"in":"4 6\n3 4 8\n4 3 8\n1 3 7\n2 4 8\n4 4 4\n1 2 1\n","out":"0 1 7 9"},{"in":"2 1\n2 1 6\n","out":"0 6"},{"in":"4 4\n4 2 7\n3 1 8\n3 3 7\n4 1 8\n","out":"0 15 8 8"},{"in":"4 7\n4 2 6\n2 2 3\n3 4 8\n4 3 2\n3 1 8\n1 2 5\n2 4 8\n","out":"0 5 8 10"}]},{"id":"cpp-pstl-17","title":"BFS On Grid","level":"Hard","statement":"Shortest path from top-left to bottom-right through \".\" cells (4-direction); print steps or -1.","input":"R C then R rows of . and #.","output":"steps.","samples":[{"in":"2 2\n..\n..\n","out":"2"}],"tests":[{"in":"2 2\n..\n..\n","out":"2"},{"in":"4 2\n..\n.#\n##\n..\n","out":"-1"},{"in":"3 5\n..#.#\n.#.##\n#.#..\n","out":"-1"},{"in":"4 3\n..#\n...\n...\n...\n","out":"5"},{"in":"4 3\n.#.\n...\n..#\n.#.\n","out":"-1"},{"in":"2 5\n....#\n.##..\n","out":"5"},{"in":"2 3\n..#\n##.\n","out":"-1"}]},{"id":"cpp-pstl-18","title":"LRU Cache With List Map","level":"Hard","statement":"Capacity C; get/put; print results of get.","input":"C, Q, then commands.","output":"gets.","samples":[{"in":"2\n4\nput 1 1\nput 2 2\nget 1\nget 3\n","out":"1\n-1"}],"tests":[{"in":"2\n4\nput 1 1\nput 2 2\nget 1\nget 3\n","out":"1\n-1"},{"in":"1\n8\nput 2 2\nget 2\nget 1\nput 1 9\nput 4 5\nget 4\nput 3 6\nput 2 8\n","out":"2\n-1\n5"},{"in":"1\n8\nput 1 6\nget 3\nput 1 9\nget 2\nget 4\nput 4 1\nget 1\nput 2 3\n","out":"-1\n-1\n-1\n-1"},{"in":"2\n8\nget 3\nput 1 2\nput 4 7\nput 1 5\nget 2\nget 4\nput 3 8\nget 2\n","out":"-1\n-1\n7\n-1"},{"in":"2\n8\nget 1\nget 3\nget 2\nput 4 9\nput 4 2\nput 2 5\nput 1 3\nput 3 4\n","out":"-1\n-1\n-1"},{"in":"1\n8\nget 3\nget 1\nput 2 5\nget 4\nget 4\nput 2 3\nput 1 8\nget 3\n","out":"-1\n-1\n-1\n-1\n-1"},{"in":"2\n8\nput 2 3\nget 1\nget 1\nput 2 7\nput 2 1\nput 2 4\nput 3 8\nput 1 1\n","out":"-1\n-1"}]},{"id":"cpp-pstl-19","title":"Top K Frequent Elements","level":"Hard","statement":"Print the K most frequent (count desc, value asc).","input":"N, list, K.","output":"K values.","samples":[{"in":"6\n1 1 1 2 2 3\n2\n","out":"1 2"}],"tests":[{"in":"6\n1 1 1 2 2 3\n2\n","out":"1 2"},{"in":"7\n3 5 3 0 4 1 5\n1\n","out":"3"},{"in":"4\n1 4 5 4\n1\n","out":"4"},{"in":"4\n0 4 4 5\n1\n","out":"4"},{"in":"8\n0 0 4 3 2 2 2 3\n1\n","out":"2"},{"in":"5\n2 4 4 1 5\n1\n","out":"4"},{"in":"10\n3 5 3 1 4 2 2 0 4 2\n1\n","out":"2"}]},{"id":"cpp-pstl-20","title":"Topological Order","level":"Hard","statement":"DAG with N nodes: print the lexicographically smallest topological order.","input":"N M then M lines \"a b\" (a before b).","output":"order.","samples":[{"in":"3 2\n1 3\n2 3\n","out":"1 2 3"}],"tests":[{"in":"3 2\n1 3\n2 3\n","out":"1 2 3"},{"in":"4 3\n1 2\n2 4\n1 3\n","out":"1 2 3 4"},{"in":"6 3\n1 5\n3 4\n1 2\n","out":"1 2 3 4 5 6"},{"in":"3 3\n1 2\n1 3\n2 3\n","out":"1 2 3"},{"in":"4 3\n3 4\n1 4\n1 3\n","out":"1 2 3 4"},{"in":"3 3\n1 3\n1 2\n2 3\n","out":"1 2 3"},{"in":"6 3\n2 3\n2 5\n3 5\n","out":"1 2 3 4 5 6"}]},{"id":"cpp-pstl-21","title":"Union Find Components","level":"Hard","statement":"Count connected components after unions.","input":"N M then M lines \"a b\".","output":"components.","samples":[{"in":"4 2\n1 2\n3 4\n","out":"2"}],"tests":[{"in":"4 2\n1 2\n3 4\n","out":"2"},{"in":"2 3\n1 1\n2 2\n2 2\n","out":"2"},{"in":"4 3\n4 2\n4 4\n2 4\n","out":"3"},{"in":"6 3\n3 6\n2 4\n1 4\n","out":"3"},{"in":"3 3\n1 3\n1 2\n2 1\n","out":"1"},{"in":"5 3\n2 2\n1 1\n3 4\n","out":"4"},{"in":"6 3\n3 4\n1 5\n1 2\n","out":"3"}]},{"id":"cpp-pstl-22","title":"Course Schedule Cycle","level":"Hard","statement":"Directed graph: print YES if it has a cycle else NO.","input":"N M then M lines \"a b\".","output":"YES/NO.","samples":[{"in":"2 2\n1 2\n2 1\n","out":"YES"}],"tests":[{"in":"2 2\n1 2\n2 1\n","out":"YES"},{"in":"4 4\n1 3\n1 2\n4 2\n1 4\n","out":"NO"},{"in":"5 4\n1 3\n2 5\n4 3\n3 2\n","out":"NO"},{"in":"4 4\n3 4\n1 2\n2 1\n4 1\n","out":"YES"},{"in":"2 4\n1 1\n2 1\n2 1\n1 2\n","out":"YES"},{"in":"4 4\n4 3\n3 4\n4 2\n1 3\n","out":"YES"},{"in":"3 4\n1 1\n1 2\n3 2\n3 3\n","out":"YES"}]}]},{"id":"pcls","title":"Classes, Templates and Operators","desc":"classes, constructors, inheritance, virtual functions, operator overloading and templates","items":[{"id":"cpp-pcls-01","title":"Class Rectangle","level":"Easy","statement":"class Rectangle with area() and perimeter().","input":"w h.","output":"\"area perimeter\".","samples":[{"in":"3 4\n","out":"12 14"}],"tests":[{"in":"3 4\n","out":"12 14"},{"in":"26\n26\n","out":"676 104"},{"in":"5\n12\n","out":"60 34"},{"in":"11\n16\n","out":"176 54"},{"in":"16\n17\n","out":"272 66"},{"in":"2\n14\n","out":"28 32"},{"in":"18\n13\n","out":"234 62"}]},{"id":"cpp-pcls-02","title":"Constructor Initializer List","level":"Easy","statement":"class Point(x, y) built with an initializer list; print \"(x, y)\".","input":"x y.","output":"text.","samples":[{"in":"1 2\n","out":"(1, 2)"}],"tests":[{"in":"1 2\n","out":"(1, 2)"},{"in":"7\n-7\n","out":"(7, -7)"},{"in":"2\n6\n","out":"(2, 6)"},{"in":"1\n7\n","out":"(1, 7)"},{"in":"-8\n7\n","out":"(-8, 7)"},{"in":"-3\n-5\n","out":"(-3, -5)"},{"in":"5\n9\n","out":"(5, 9)"}]},{"id":"cpp-pcls-03","title":"Counter Class","level":"Easy","statement":"class Counter with inc/dec and a getter. Apply commands, print value.","input":"N, then inc/dec.","output":"value.","samples":[{"in":"3\ninc\ninc\ndec\n","out":"1"}],"tests":[{"in":"3\ninc\ninc\ndec\n","out":"1"},{"in":"5\ninc\ndec\ndec\ninc\ndec\n","out":"-1"},{"in":"5\ndec\ninc\ndec\ndec\ninc\n","out":"-1"},{"in":"5\ninc\ndec\ninc\ndec\ndec\n","out":"-1"},{"in":"5\ninc\ninc\ninc\ndec\ninc\n","out":"3"},{"in":"5\ninc\ninc\ndec\ndec\ndec\n","out":"-1"},{"in":"5\ninc\ninc\ninc\ninc\ninc\n","out":"5"}]},{"id":"cpp-pcls-04","title":"Const Member Getter","level":"Easy","statement":"Class Circle with const double area() (3.14159*r*r). Print 2 decimals.","input":"r.","output":"area.","samples":[{"in":"3\n","out":"28.27"}],"tests":[{"in":"3\n","out":"28.27"},{"in":"7\n","out":"153.94"},{"in":"5\n","out":"78.54"},{"in":"6\n","out":"113.10"},{"in":"20\n","out":"1256.64"},{"in":"4\n","out":"50.27"},{"in":"9\n","out":"254.47"}]},{"id":"cpp-pcls-05","title":"Static Member Count","level":"Easy","statement":"A static member counts objects created. Create N and print the count.","input":"N.","output":"N.","samples":[{"in":"4\n","out":"4"}],"tests":[{"in":"4\n","out":"4"},{"in":"36\n","out":"36"},{"in":"10\n","out":"10"},{"in":"12\n","out":"12"},{"in":"33\n","out":"33"},{"in":"3\n","out":"3"},{"in":"21\n","out":"21"}]},{"id":"cpp-pcls-06","title":"Struct Student Total","level":"Easy","statement":"struct with name and 3 marks; print \"name total\".","input":"name m1 m2 m3.","output":"\"name total\".","samples":[{"in":"Asha 1 2 3\n","out":"Asha 6"}],"tests":[{"in":"Asha 1 2 3\n","out":"Asha 6"},{"in":"Dev 33 71 38\n","out":"Dev 142"},{"in":"Asha 31 51 52\n","out":"Asha 134"},{"in":"Dev 47 63 73\n","out":"Dev 183"},{"in":"Dev 23 82 49\n","out":"Dev 154"},{"in":"Dev 37 42 39\n","out":"Dev 118"},{"in":"Dev 72 35 4\n","out":"Dev 111"}]},{"id":"cpp-pcls-07","title":"Default Argument Function","level":"Easy","statement":"Write area(int w, int h = 1). Lines are \"w\" or \"w h\": print each area.","input":"N, then N lines.","output":"areas.","samples":[{"in":"2\n5\n3 4\n","out":"5\n12"}],"tests":[{"in":"2\n5\n3 4\n","out":"5\n12"},{"in":"3\n7 2\n1\n2 8\n","out":"14\n1\n16"},{"in":"3\n2 9\n1 3\n3 5\n","out":"18\n3\n15"},{"in":"3\n7\n2 6\n7 5\n","out":"7\n12\n35"},{"in":"3\n8 2\n1\n4 2\n","out":"16\n1\n8"},{"in":"3\n6 2\n3\n4 2\n","out":"12\n3\n8"},{"in":"3\n9\n2\n3 7\n","out":"9\n2\n21"}]},{"id":"cpp-pcls-08","title":"Operator Plus Vector","level":"Medium","statement":"Overload operator+ for Vec(x,y); print \"(x, y)\".","input":"\"x1 y1\" then \"x2 y2\".","output":"sum.","samples":[{"in":"1 2\n3 4\n","out":"(4, 6)"}],"tests":[{"in":"1 2\n3 4\n","out":"(4, 6)"},{"in":"4 1\n-2 1\n","out":"(2, 2)"},{"in":"1 -1\n-5 1\n","out":"(-4, 0)"},{"in":"-5 -4\n-2 -5\n","out":"(-7, -9)"},{"in":"5 -3\n-4 3\n","out":"(1, 0)"},{"in":"-2 5\n-1 -2\n","out":"(-3, 3)"},{"in":"1 -3\n-2 0\n","out":"(-1, -3)"}]},{"id":"cpp-pcls-09","title":"Virtual Function Shapes","level":"Medium","statement":"Base Shape with virtual area(); lines \"circle r\" or \"rect w h\"; print each area (pi=3.14159, 2 decimals).","input":"N, then N lines.","output":"areas.","samples":[{"in":"2\ncircle 1\nrect 2 3\n","out":"3.14\n6.00"}],"tests":[{"in":"2\ncircle 1\nrect 2 3\n","out":"3.14\n6.00"},{"in":"3\nrect 3 4\ncircle 9\nrect 1 7\n","out":"12.00\n254.47\n7.00"},{"in":"3\nrect 1 4\ncircle 3\nrect 2 8\n","out":"4.00\n28.27\n16.00"},{"in":"3\ncircle 2\ncircle 2\ncircle 3\n","out":"12.57\n12.57\n28.27"},{"in":"3\nrect 9 9\ncircle 1\nrect 8 4\n","out":"81.00\n3.14\n32.00"},{"in":"3\nrect 9 5\ncircle 6\ncircle 4\n","out":"45.00\n113.10\n50.27"},{"in":"3\ncircle 2\nrect 9 9\nrect 4 4\n","out":"12.57\n81.00\n16.00"}]},{"id":"cpp-pcls-10","title":"Template Max Function","level":"Medium","statement":"template<T> T maxOf(T a, T b). Lines are \"i a b\" (ints) or \"d a b\" (doubles, print 1 decimal).","input":"N, then N lines.","output":"maxima.","samples":[{"in":"2\ni 3 9\nd 1.5 0.5\n","out":"9\n1.5"}],"tests":[{"in":"2\ni 3 9\nd 1.5 0.5\n","out":"9\n1.5"},{"in":"3\ni 2 8\nd 2.0 0.5\nd 3.5 4.0\n","out":"8\n2.0\n4.0"},{"in":"3\nd 3.0 4.0\nd 3.0 0.0\nd 2.5 4.5\n","out":"4.0\n3.0\n4.5"},{"in":"3\ni 7 5\ni 4 9\ni 4 0\n","out":"7\n9\n4"},{"in":"3\ni 9 9\nd 2.0 4.0\nd 3.5 2.5\n","out":"9\n4.0\n3.5"},{"in":"3\nd 4.0 0.5\nd 2.5 3.5\nd 2.0 2.5\n","out":"4.0\n3.5\n2.5"},{"in":"3\ni 6 8\nd 3.0 2.0\ni 0 7\n","out":"8\n3.0\n7"}]},{"id":"cpp-pcls-11","title":"Stack Class Template","level":"Medium","statement":"Template stack with push/pop/top; EMPTY on empty pop/top.","input":"N, commands push X/pop/peek.","output":"pop/peek lines.","samples":[{"in":"4\npush 1\npeek\npop\npop\n","out":"1\n1\nEMPTY"}],"tests":[{"in":"4\npush 1\npeek\npop\npop\n","out":"1\n1\nEMPTY"},{"in":"6\npush 9\npop\npeek\npush 8\npeek\npeek\n","out":"9\nEMPTY\n8\n8"},{"in":"6\npeek\npop\npop\npeek\npop\npeek\n","out":"EMPTY\nEMPTY\nEMPTY\nEMPTY\nEMPTY\nEMPTY"},{"in":"6\npop\npeek\npeek\npop\npop\npop\n","out":"EMPTY\nEMPTY\nEMPTY\nEMPTY\nEMPTY\nEMPTY"},{"in":"6\npop\npush 4\npeek\npeek\npush 1\npeek\n","out":"EMPTY\n4\n4\n1"},{"in":"6\npush 5\npeek\npeek\npush 2\npeek\npop\n","out":"5\n5\n2\n2"},{"in":"6\npop\npush 3\npeek\npush 6\npeek\npush 7\n","out":"EMPTY\n3\n6"}]},{"id":"cpp-pcls-12","title":"Comparison Operator Sort","level":"Medium","statement":"Records \"name mark\" with operator<: higher mark first then name. Print names.","input":"N, then lines.","output":"names.","samples":[{"in":"3\nb 5\na 5\nc 9\n","out":"c a b"}],"tests":[{"in":"3\nb 5\na 5\nc 9\n","out":"c a b"},{"in":"4\na 1\nb 0\nc 1\nd 1\n","out":"a c d b"},{"in":"4\na 1\nb 2\nc 0\nd 1\n","out":"b a d c"},{"in":"4\na 3\nb 2\nc 0\nd 1\n","out":"a b d c"},{"in":"4\na 3\nb 1\nc 1\nd 1\n","out":"a b c d"},{"in":"4\na 0\nb 2\nc 3\nd 2\n","out":"c b d a"},{"in":"4\na 0\nb 0\nc 0\nd 2\n","out":"d a b c"}]},{"id":"cpp-pcls-13","title":"Bank Account Class","level":"Medium","statement":"Account with deposit/withdraw/balance; INSUFFICIENT when too much.","input":"start, N, commands.","output":"replies.","samples":[{"in":"100\n3\ndeposit 50\nwithdraw 200\nbalance\n","out":"INSUFFICIENT\n150"}],"tests":[{"in":"100\n3\ndeposit 50\nwithdraw 200\nbalance\n","out":"INSUFFICIENT\n150"},{"in":"68\n2\nwithdraw 1\nbalance\n","out":"67"},{"in":"21\n1\nbalance\n","out":"21"},{"in":"88\n6\ndeposit 30\nbalance\nwithdraw 46\nbalance\nbalance\nbalance\n","out":"118\n72\n72\n72"},{"in":"12\n8\nbalance\nwithdraw 49\ndeposit 39\nbalance\nbalance\nwithdraw 60\nwithdraw 15\nbalance\n","out":"12\nINSUFFICIENT\n51\n51\nINSUFFICIENT\n36"},{"in":"65\n6\ndeposit 10\nbalance\ndeposit 5\nbalance\ndeposit 50\ndeposit 14\n","out":"75\n80"},{"in":"17\n6\nwithdraw 39\nbalance\nbalance\nbalance\ndeposit 37\nwithdraw 29\n","out":"INSUFFICIENT\n17\n17\n17"}]},{"id":"cpp-pcls-14","title":"Fraction Class Reduce","level":"Medium","statement":"Fraction with operator+ reduced to lowest terms: print \"p/q\".","input":"a b c d.","output":"p/q.","samples":[{"in":"1 2 1 3\n","out":"5/6"}],"tests":[{"in":"1 2 1 3\n","out":"5/6"},{"in":"3 6 4 4\n","out":"3/2"},{"in":"3 1 1 6\n","out":"19/6"},{"in":"6 3 6 2\n","out":"5/1"},{"in":"5 4 4 1\n","out":"21/4"},{"in":"3 3 5 3\n","out":"8/3"},{"in":"1 3 2 2\n","out":"4/3"}]},{"id":"cpp-pcls-15","title":"Matrix Class Multiply","level":"Hard","statement":"Class Matrix2 with operator*; print rows.","input":"two lines of 4 numbers.","output":"two rows.","samples":[{"in":"1 2 3 4\n5 6 7 8\n","out":"19 22\n43 50"}],"tests":[{"in":"1 2 3 4\n5 6 7 8\n","out":"19 22\n43 50"},{"in":"-3 2 -1 1\n-3 -3 4 -1\n","out":"17 7\n7 2"},{"in":"1 2 1 0\n0 -1 5 3\n","out":"10 5\n0 -1"},{"in":"-3 -1 1 -1\n2 4 3 -3\n","out":"-9 -9\n-1 7"},{"in":"-3 4 4 2\n-3 2 -1 1\n","out":"5 -2\n-14 10"},{"in":"-2 5 -1 1\n2 -1 -2 0\n","out":"-14 2\n-4 1"},{"in":"1 3 3 -2\n1 -2 5 4\n","out":"16 10\n-7 -14"}]},{"id":"cpp-pcls-16","title":"Big Integer Class Add","level":"Hard","statement":"Class BigInt storing digits with operator+. Add two numbers up to 50 digits.","input":"two numbers.","output":"sum.","samples":[{"in":"99999999999999999999\n1\n","out":"100000000000000000000"}],"tests":[{"in":"99999999999999999999\n1\n","out":"100000000000000000000"},{"in":"98175589543084836013740\n21854727285538956636953098293349267\n","out":"21854727285637132226496183129363007"},{"in":"35350873574469884170947188608340973715715697242\n81287279919129825763970321\n","out":"35350873574469884171028475888260103541479667563"},{"in":"343377010979558259426902113682819230750\n756567296048060\n","out":"343377010979558259426902870250115278810"},{"in":"262539822618626207373554588681539673818\n6314897157338350227372648015305786062015043202\n","out":"6314897419878172845998855388860374743554717020"},{"in":"158998744609130183734406586640574633216020222127\n82733125407028409637\n","out":"158998744609130183734406586723307758623048631764"},{"in":"90555236510517\n5156346152428196487\n","out":"5156436707664707004"}]},{"id":"cpp-pcls-17","title":"Polymorphic Employee Payroll","level":"Hard","statement":"Base Employee virtual pay(): manager base*2, engineer base+1000, intern base. Print total.","input":"N, lines \"kind base\".","output":"total.","samples":[{"in":"2\nmanager 100\nintern 40\n","out":"240"}],"tests":[{"in":"2\nmanager 100\nintern 40\n","out":"240"},{"in":"3\nmanager 50\nintern 256\nintern 25\n","out":"381"},{"in":"3\nintern 440\nmanager 432\nengineer 414\n","out":"2718"},{"in":"3\nmanager 402\nintern 188\nintern 258\n","out":"1250"},{"in":"3\nengineer 444\nintern 192\nengineer 217\n","out":"2853"},{"in":"3\nintern 130\nmanager 380\nintern 16\n","out":"906"},{"in":"3\nintern 423\nmanager 486\nintern 71\n","out":"1466"}]},{"id":"cpp-pcls-18","title":"Priority Task Manager","level":"Hard","statement":"add name priority / next (highest priority, earliest on tie) or EMPTY.","input":"N, commands.","output":"next replies.","samples":[{"in":"4\nadd a 1\nadd b 5\nnext\nnext\n","out":"b\na"}],"tests":[{"in":"4\nadd a 1\nadd b 5\nnext\nnext\n","out":"b\na"},{"in":"7\nadd c 2\nadd c 3\nnext\nadd b 2\nadd a 2\nadd c 2\nadd a 3\n","out":"c"},{"in":"7\nnext\nadd b 3\nnext\nadd c 3\nnext\nnext\nadd c 2\n","out":"EMPTY\nb\nc\nEMPTY"},{"in":"7\nnext\nnext\nnext\nadd b 2\nadd c 2\nadd a 1\nadd c 2\n","out":"EMPTY\nEMPTY\nEMPTY"},{"in":"7\nnext\nadd a 2\nnext\nadd c 3\nnext\nadd c 2\nadd a 2\n","out":"EMPTY\na\nc"},{"in":"7\nnext\nadd c 3\nnext\nnext\nadd b 2\nnext\nadd a 2\n","out":"EMPTY\nc\nEMPTY\nb"},{"in":"7\nnext\nadd b 2\nnext\nadd a 2\nnext\nadd b 1\nadd b 2\n","out":"EMPTY\nb\na"}]},{"id":"cpp-pcls-19","title":"Observer Pattern","level":"Hard","statement":"sub/unsub/publish with delivery lines \"name got msg\".","input":"N, commands.","output":"deliveries.","samples":[{"in":"3\nsub a\nsub b\npublish hi\n","out":"a got hi\nb got hi"}],"tests":[{"in":"3\nsub a\nsub b\npublish hi\n","out":"a got hi\nb got hi"},{"in":"6\nsub b\nsub b\nsub a\npublish hi\nsub b\nsub a\n","out":"b got hi\na got hi"},{"in":"6\npublish hi\nsub a\npublish hi\npublish hi\nsub b\nsub b\n","out":"a got hi\na got hi"},{"in":"6\nunsub a\nsub b\nunsub a\nunsub a\nunsub a\npublish hi\n","out":"b got hi"},{"in":"6\nsub b\nunsub a\nsub b\nunsub a\nunsub a\nsub b\n","out":"NONE"},{"in":"6\nsub a\nsub a\npublish hi\nsub b\nunsub a\nunsub a\n","out":"a got hi"},{"in":"6\nsub b\nsub b\nunsub a\nsub a\nunsub a\nunsub a\n","out":"NONE"}]},{"id":"cpp-pcls-20","title":"Parking Lot Simulation","level":"Hard","statement":"park/leave with PARKED/FULL/LEFT/MISSING replies.","input":"C, N, commands.","output":"replies.","samples":[{"in":"1\n3\npark a\npark b\nleave a\n","out":"PARKED\nFULL\nLEFT"}],"tests":[{"in":"1\n3\npark a\npark b\nleave a\n","out":"PARKED\nFULL\nLEFT"},{"in":"1\n7\nleave b\npark b\npark b\npark c\nleave a\npark b\npark a\n","out":"MISSING\nPARKED\nFULL\nFULL\nMISSING\nFULL\nFULL"},{"in":"1\n7\npark a\npark c\nleave a\nleave b\npark a\npark a\npark c\n","out":"PARKED\nFULL\nLEFT\nMISSING\nPARKED\nFULL\nFULL"},{"in":"2\n7\nleave b\nleave b\npark a\npark a\npark c\nleave b\nleave b\n","out":"MISSING\nMISSING\nPARKED\nFULL\nPARKED\nMISSING\nMISSING"},{"in":"1\n7\npark a\npark c\nleave b\npark a\npark c\nleave b\npark c\n","out":"PARKED\nFULL\nMISSING\nFULL\nFULL\nMISSING\nFULL"},{"in":"1\n7\nleave b\npark a\nleave a\nleave b\nleave b\npark b\npark b\n","out":"MISSING\nPARKED\nLEFT\nMISSING\nMISSING\nPARKED\nFULL"},{"in":"2\n7\nleave a\npark a\npark c\nleave b\npark a\npark a\npark b\n","out":"MISSING\nPARKED\nPARKED\nMISSING\nFULL\nFULL\nFULL"}]},{"id":"cpp-pcls-21","title":"Inventory With Classes","level":"Hard","statement":"add/remove/total with SHORT on insufficient removals.","input":"N, commands.","output":"replies.","samples":[{"in":"3\nadd a 5\nremove a 7\ntotal\n","out":"SHORT\n5"}],"tests":[{"in":"3\nadd a 5\nremove a 7\ntotal\n","out":"SHORT\n5"},{"in":"7\nadd a 5\ntotal\nadd a 1\nadd b 3\nadd a 3\ntotal\nremove b 3\n","out":"5\n12"},{"in":"7\nremove b 6\nadd a 5\nremove a 4\ntotal\nadd b 3\nremove a 6\ntotal\n","out":"SHORT\n1\nSHORT\n4"},{"in":"7\ntotal\nadd b 4\ntotal\nadd a 3\nadd a 5\nremove b 1\ntotal\n","out":"0\n4\n11"},{"in":"7\nremove b 1\nadd a 5\nadd b 3\nadd b 5\nremove a 1\nremove b 3\nremove b 1\n","out":"SHORT"},{"in":"7\nremove a 2\nremove a 2\nadd a 3\ntotal\nadd a 2\nadd b 1\nadd a 3\n","out":"SHORT\nSHORT\n3"},{"in":"7\nadd b 2\nadd a 4\nadd b 1\nremove a 5\nadd a 3\nadd a 1\nadd b 4\n","out":"SHORT"}]}]}]};